-- Lernquest Testphase (Entscheidung der Lehrkraft am 12.11.2026, Projekt „baukasten“): Erst soll der Lern- und
-- Spielablauf funktionieren. Alle bisher freigeschalteten Stationen werden deaktiviert und zwei Teststationen
-- freigeschaltet („to be“ und „Singular and plural“, mit Hilfe-Karten, Tipps und eingestreuter Wiederholung;
-- Quelle: src/lernquest/testpakete.ts).
-- Deaktivieren heißt: Die Pakete wandern in lq_paket_archiv (nichts geht verloren; zurückholen mit
-- insert into lq_paket select klasse, stunde, daten, stand from lq_paket_archiv …). Spielstände bleiben.

create table if not exists public.lq_paket_archiv (
  klasse uuid not null,
  stunde text not null,
  daten jsonb not null,
  stand timestamptz,
  archiviert timestamptz not null default now()
);
alter table public.lq_paket_archiv enable row level security;
revoke all on public.lq_paket_archiv from anon, authenticated;

insert into public.lq_paket_archiv (klasse, stunde, daten, stand)
  select p.klasse, p.stunde, p.daten, p.stand from public.lq_paket p;
delete from public.lq_paket;

insert into public.lq_paket (klasse, stunde, daten)
  select k.id, t.stunde, t.daten from public.lq_klasse k cross join (values
  ('test-to-be', $json${"format": "lernquest-paket", "v": 1, "stunde": "test-to-be", "nummer": 1, "titel": "The verb „to be“", "modul": {"id": "test-grammatik-start", "nummer": 1, "titel": "Test: Grammatik-Start", "icon": "", "stunden": [{"nummer": 1, "titel": "The verb „to be“"}, {"nummer": 2, "titel": "Singular and plural"}]}, "fach": "Englisch", "lang": "en", "hilfe": [{"titel": "„to be“ heißt „sein“", "text": "„to be“ hat drei Formen: am, is und are. Welche du nimmst, hängt davon ab, wer gemeint ist.", "beispiele": ["I {{am}} Tom.", "You {{are}} my friend.", "She {{is}} ten.", "We {{are}} in class 5c."]}, {"titel": "Wer bekommt welche Form?", "text": "I → am. He, she, it (und ein Name oder ein Ding) → is. You, we, they (und mehrere) → are.", "beispiele": ["Tom {{is}} tall.", "The dog {{is}} brown.", "They {{are}} at school."]}, {"titel": "Kurzformen", "text": "Beim Sprechen werden die Formen oft kurz. Der Apostroph steht für den Buchstaben, der wegfällt.", "beispiele": ["I am → I{{’m}}", "she is → she{{’s}}", "we are → we{{’re}}"]}], "uebungen": [{"art": "waehlen", "id": "tb-1", "frage": "Welche Form von „to be“ passt zu „I“?", "optionen": ["am", "is", "are"], "richtig": [0], "erklaerung": "Zu I gehört immer am: I am.", "tipp": "Schau auf die erste Karte: I hat seine ganz eigene Form.", "niveau": 1}, {"art": "waehlen", "id": "tb-2", "frage": "Welche Form passt zu „she“?", "optionen": ["am", "is", "are"], "richtig": [1], "erklaerung": "she → is: She is ten.", "tipp": "He, she und it teilen sich eine Form.", "niveau": 1}, {"art": "waehlen", "id": "tb-3", "frage": "Welche Form passt zu „they“?", "optionen": ["am", "is", "are"], "richtig": [2], "erklaerung": "you, we und they → are.", "tipp": "„they“ meint mehrere Personen.", "niveau": 1}, {"art": "paare", "id": "tb-4", "frage": "Finde die Paare.", "paare": [["I", "am"], ["she", "is"], ["they", "are"]], "erklaerung": "I am, she is, they are.", "tipp": "Jede Person bekommt ihre Form – die zweite Karte hilft.", "niveau": 1}, {"art": "richtigfalsch", "id": "tb-5", "frage": "Stimmt das?", "aussage": "He is my brother.", "richtig": true, "erklaerung": "he → is. Der Satz stimmt.", "tipp": "Welche Form gehört zu he?", "niveau": 1}, {"art": "richtigfalsch", "id": "tb-6", "frage": "Stimmt das?", "aussage": "We is in class 5c.", "richtig": false, "erklaerung": "Richtig ist: We are in class 5c.", "tipp": "Bei „we“ sind mehrere gemeint.", "niveau": 1}, {"art": "luecke", "id": "tb-7", "frage": "Ergänze die Lücke.", "teile": ["I ", "am", " eleven years old."], "kacheln": ["is", "are", "am"], "erklaerung": "Zu I gehört am.", "tipp": "Wer spricht hier? I → …", "niveau": 2}, {"art": "luecke", "id": "tb-8", "frage": "Ergänze die Lücke.", "teile": ["My sister ", "is", " at home."], "kacheln": ["am", "is", "are"], "erklaerung": "my sister = she → is.", "tipp": "„my sister“ ist eine Person – wie she.", "niveau": 2}, {"art": "luecke", "id": "tb-9", "frage": "Ergänze die Lücke.", "teile": ["Tom and Lisa ", "are", " friends."], "kacheln": ["am", "are", "is"], "erklaerung": "Mehrere Personen → are.", "tipp": "Zwei Personen: Tom und Lisa = they.", "niveau": 2}, {"art": "gruppen", "id": "tb-10", "frage": "Sortiere: is oder are?", "gruppen": ["is", "are"], "karten": [["he", 0], ["it", 0], ["my dog", 0], ["we", 1], ["you", 1], ["my friends", 1]], "erklaerung": "he, it, my dog → is; we, you, my friends → are.", "tipp": "Einer (he, she, it) → is. Mehrere oder you → are.", "niveau": 2}, {"art": "reihenfolge", "id": "tb-11", "frage": "Bring die Wörter in die richtige Reihenfolge.", "hinweis": "", "kacheln": [".", "friend", "my", "She", "is", "best"], "loesung": "She is my best friend.", "erklaerung": "She is my best friend.", "tipp": "Der Satz fängt mit „She“ an, danach kommt die Form von to be.", "niveau": 2}, {"art": "waehlen", "id": "tb-12", "frage": "Was passt in die Frage?", "aussage": "___ you twelve?", "optionen": ["Are", "Is", "Am"], "richtig": [0], "erklaerung": "you → are: Are you twelve?", "tipp": "Bei Fragen rückt die Form von to be nach vorn. Wer ist gemeint?", "niveau": 2}, {"art": "schreiben", "id": "tb-13", "frage": "Schreib die richtige Form von „to be“.", "aussage": "The cat ___ black.", "loesungen": ["is"], "erklaerung": "the cat = it → is.", "tipp": "„the cat“ ist ein Tier – wie it.", "niveau": 3}, {"art": "schreiben", "id": "tb-14", "frage": "Schreib die richtige Form von „to be“.", "aussage": "I ___ from Germany.", "loesungen": ["am"], "erklaerung": "I am from Germany.", "tipp": "I hat seine eigene Form.", "niveau": 3}, {"art": "schreiben", "id": "tb-15", "frage": "Schreib die Kurzform.", "aussage": "we are", "loesungen": ["we’re", "we're"], "erklaerung": "we are → we’re.", "tipp": "Das a fällt weg, dafür kommt ein Apostroph.", "niveau": 3}]}$json$::jsonb),
  ('test-plural', $json${"format": "lernquest-paket", "v": 1, "stunde": "test-plural", "nummer": 2, "titel": "Singular and plural", "modul": {"id": "test-grammatik-start", "nummer": 1, "titel": "Test: Grammatik-Start", "icon": "", "stunden": [{"nummer": 1, "titel": "The verb „to be“"}, {"nummer": 2, "titel": "Singular and plural"}]}, "fach": "Englisch", "lang": "en", "hilfe": [{"titel": "Einzahl und Mehrzahl", "text": "Singular heißt Einzahl (eins), Plural heißt Mehrzahl (mehrere). Meistens hängst du einfach -s an.", "beispiele": ["one cat → two cat{{s}}", "a book → three book{{s}}", "a girl → many girl{{s}}"]}, {"titel": "-es nach s, x, sh und ch", "text": "Endet das Wort auf s, x, sh oder ch, hängst du -es an. So kann man es besser sprechen.", "beispiele": ["a box → two box{{es}}", "a bus → two bus{{es}}", "a watch → two watch{{es}}"]}, {"titel": "Ausnahmen", "text": "Ein paar Wörter sind ganz anders. Die lernst du am besten auswendig.", "beispiele": ["a man → two {{men}}", "a child → two {{children}}", "a mouse → two {{mice}}"]}], "uebungen": [{"art": "waehlen", "id": "pl-1", "frage": "Was ist Plural (mehrere)?", "optionen": ["cats", "cat"], "richtig": [0], "erklaerung": "cats sind mehrere Katzen.", "tipp": "Plural heißt: mehr als eins.", "niveau": 1}, {"art": "waehlen", "id": "pl-2", "frage": "Wie heißt der Plural von „book“?", "optionen": ["books", "bookes", "book"], "richtig": [0], "erklaerung": "book → books.", "tipp": "Meistens hängst du nur -s an.", "niveau": 1}, {"art": "richtigfalsch", "id": "pl-3", "frage": "Stimmt das?", "aussage": "one dog – two dogs", "richtig": true, "erklaerung": "dog + s = dogs.", "tipp": "dog ist ein ganz normales Wort.", "niveau": 1}, {"art": "waehlen", "id": "pl-4", "frage": "Wiederholung: Was passt?", "aussage": "The dogs ___ hungry.", "optionen": ["are", "is"], "richtig": [0], "erklaerung": "Plural → are: The dogs are hungry.", "tipp": "Mehrere Hunde = they.", "niveau": 1}, {"art": "paare", "id": "pl-5", "frage": "Finde die Paare.", "paare": [["cat", "cats"], ["box", "boxes"], ["man", "men"], ["pen", "pens"]], "erklaerung": "cats, boxes, men, pens.", "tipp": "Achte auf die Endung – und denk an die Ausnahmen.", "niveau": 1}, {"art": "gruppen", "id": "pl-6", "frage": "Sortiere: -s oder -es?", "gruppen": ["-s", "-es"], "karten": [["book", 0], ["apple", 0], ["girl", 0], ["box", 1], ["bus", 1], ["watch", 1]], "erklaerung": "books, apples, girls – aber boxes, buses, watches.", "tipp": "Endet das Wort auf s, x, sh oder ch? Dann -es.", "niveau": 2}, {"art": "luecke", "id": "pl-7", "frage": "Ergänze die Lücke.", "teile": ["I have got two ", "sisters", "."], "kacheln": ["sisteres", "sisters", "sister"], "erklaerung": "two sisters: Plural mit -s.", "tipp": "„two“ heißt: mehr als eins.", "niveau": 2}, {"art": "luecke", "id": "pl-8", "frage": "Ergänze die Lücke.", "teile": ["My brothers ", "are", " at school."], "kacheln": ["are", "am", "is"], "erklaerung": "Mehrere → are.", "tipp": "Wiederholung: „my brothers“ sind mehrere = they.", "niveau": 2}, {"art": "luecke", "id": "pl-9", "frage": "Ergänze die Lücke.", "teile": ["There are three ", "boxes", " on the table."], "kacheln": ["boxes", "boxs", "box"], "erklaerung": "box → boxes.", "tipp": "box endet auf x – schau auf die zweite Karte.", "niveau": 2}, {"art": "waehlen", "id": "pl-10", "frage": "Wie heißt der Plural von „child“?", "optionen": ["children", "childs", "childes"], "richtig": [0], "erklaerung": "child → children.", "tipp": "child ist eine Ausnahme – schau auf die Karte „Ausnahmen“.", "niveau": 2}, {"art": "richtigfalsch", "id": "pl-11", "frage": "Stimmt das?", "aussage": "two mans", "richtig": false, "erklaerung": "Richtig ist: two men.", "tipp": "man ist unregelmäßig.", "niveau": 2}, {"art": "reihenfolge", "id": "pl-12", "frage": "Bring die Wörter in die richtige Reihenfolge.", "hinweis": "", "kacheln": ["black", "cats", "The", ".", "are"], "loesung": "The cats are black.", "erklaerung": "The cats are black.", "tipp": "Wiederholung: Fang mit „The cats“ an. Mehrere Katzen → are.", "niveau": 2}, {"art": "schreiben", "id": "pl-13", "frage": "Schreib den Plural.", "aussage": "a bus", "loesungen": ["buses"], "erklaerung": "bus → buses.", "tipp": "bus endet auf s.", "niveau": 3}, {"art": "schreiben", "id": "pl-14", "frage": "Schreib den Plural.", "aussage": "a girl", "loesungen": ["girls"], "erklaerung": "girl → girls.", "tipp": "Ganz normal: nur -s.", "niveau": 3}, {"art": "schreiben", "id": "pl-15", "frage": "Schreib den Plural.", "aussage": "a mouse", "loesungen": ["mice"], "erklaerung": "mouse → mice.", "tipp": "Ausnahme! Schau auf die Karte „Ausnahmen“.", "niveau": 3}, {"art": "schreiben", "id": "pl-16", "frage": "Schreib die richtige Form von „to be“.", "aussage": "The children ___ happy.", "loesungen": ["are"], "erklaerung": "children → are.", "tipp": "Wiederholung: children sind mehrere = they.", "niveau": 3}]}$json$::jsonb)
  ) as t(stunde, daten);
